import type {EnsembleOption} from './ensemble-story-types.ts';

/** Foreground exchanges are authored independently of the public effect ledger.
 * Looking, reading, and asking a clarification do not resolve a game action. */
export type EnsembleOpening = {speakerId:string;speech:string;activity:string};
export type EncounterClarification = {question:string;answer:string};
type Dialogue = {body:string;opening:EnsembleOpening;clarification?:EncounterClarification};
const scene=(speakerId:string,body:string,speech:string,activity:string,question?:string,answer?:string):Dialogue=>({body,opening:{speakerId,speech,activity},...(question&&answer?{clarification:{question,answer}}:{})});
export const ensembleDialogue:Record<string,Dialogue>={
 'whaleskin:fit':scene('lata_rao',
  "Lata pulls the cover toward the rear doors, releases it when the fabric resists, and tries again with the restrained patience she usually reserves for somebody else’s loading. “Universal,” she says, reading the packet. Tavi, whose loaded produce platform needs protection before the rain, asks which universe the manufacturer had in mind. Lata offers them the Whaleskin before the conversation can become a measurement; while Tavi spreads it above the vegetables, one loose sleeve slips below the platform, unnoticed by everyone except Mara, who is looking toward the outlet. There is still time to check where the water will go.",
  'The mirrors fit beautifully. Tavi needs a cover, I have a cover; that is a rather better use of the afternoon than discussing the rear doors. Will you help us get it settled?',
  'Keeps a thumb over the packet’s measurement diagram.', 'Why does the outlet matter?',
  'Mara points beneath the platform. “The cover keeps rain off the vegetables. It must also leave the outlet clear, or the water stays here.” Tavi lifts the loose corner without fastening it. Nothing has been installed or checked yet.'),
 'whaleskin:rain':scene('lata_rao',
  "Rain stipples the empty lines in Lata’s delivery book while the road remains closed for inspection, and Ravi, whose alternative route is still usable, has begun describing the grocery trips he could carry. Lata listens until he mentions how efficiently Mara is working. “Your wife,” she says, with an emphasis that makes him smile before he understands it. Mara puts her report on the landing desk, where it can answer a question about the road rather more precisely than the conversation about her marriage; you can ask for those findings, repeat Lata’s suspicion, or keep to your own journey.",
  'Every empty line in this book was supposed to be a delivery. Ravi has found something encouraging to say about all of them. I would prefer a time when I can drive through.',
  'Shields the delivery book from the rain with the unused packet.', 'What has Mara actually found?',
  '“The road needs its inspection before anyone uses it,” Mara says. “Ravi’s orders don’t tell you what is under that platform.” Asking to hear her report is different from repeating the theory about her marriage.'),
 'whaleskin:sleeve':scene('lata_rao',
  "After the trained crew makes the outlet safe, a silver mirror sleeve emerges from beneath Tavi’s platform, followed by more of the remarkably universal cover. Tavi sets a spoiled crate beside the sound produce and opens the dated notes, taking care that none of the pages sticks to the wet wood. Lata takes hold of the cleared sheet just as somebody raises a camera, so that, in a close photograph of the rescue, she would be very well positioned. A wider frame would contain the crate, the inspection, and the reason the crew came; she looks from one edge of the possible picture to the other.",
  'If you come closer, you can see the useful part of what I’m doing. I would have thought that was the point of taking a photograph. Tavi’s notes will still be there afterward.',
  'Looks from the raised camera to the crate at the edge of its frame.', 'Whose cover is it now?',
  '“Mine,” Tavi says. “Lata gave it to me for the platform.” They leave their notes beside the crate. Helping move the cover does not return it to Lata or remove Tavi’s account of the loss.'),
 'whaleskin:next':scene('lata_rao',
  "With the road safe again, the argument must survive contact with ordinary work: Lata and Ravi spread their order sheets on separate parts of the landing desk, then keep reaching into the middle to demonstrate how naturally the routes could fit together. Tavi takes the Whaleskin back to the checked platform while the two drivers debate a journey neither has yet priced. The accepted grocery orders remain on their own sheets, impervious to the enthusiasm developing above them. Asking Lata for the inland rate might turn the conversation into something useful; leaving the routes separate, or leaving altogether, would also produce a recognizable ending.",
  'My inland route is not the blank space on Ravi’s map. It uses fuel, and it takes an afternoon. If he wants a price, I can give him one considerably faster than another explanation.',
  'Moves her order sheet out from under Ravi’s larger map.', 'Are the routes already combined?',
  'Lata shakes her head. “There are accepted orders. There is also Ravi’s suggestion. I keep those on different sheets.” A price discussion does not purchase another delivery or enlist you in either route.'),
 'extra_run:demand':scene('ravi_desai',
  "Ravi has drawn columns for a regular grocery service before finding enough names to fill the first departure, leaving an expanse of paper he describes as flexibility. When Lata asks which journey he means and Tavi asks how much produce is aboard, he answers a question about potential customers that neither of them has quite asked. A single order would give him one delivery; the paid two-delivery trial would give him a second departure to staff, which he mentions only after describing how conveniently the first could lead to it. He leaves the pencil above your empty line and waits.",
  'I can combine the shipments people have ordered. The trick is knowing which people are about to order them. Are you thinking of one delivery, or shall I explain why two makes a very tidy beginning?',
  'Holds the pencil above the customer column without writing your name.', 'What would I be buying?',
  '“One delivery or the two-delivery trial at the price shown,” Ravi says. He draws a line below the second box. “Nothing underneath that until there is another order.”'),
 'extra_run:terms':scene('ravi_desai',
  "The load on the landing has a weight and a departure time that the proposed service, when Ravi first described it, managed to exist without. He checks the crates against the order sheet, reaches the space reserved for a loader’s name, and begins a sentence about tomorrow. Lata taps today’s column until he returns to it. One quoted loading commitment would get the booked shipment away; a smaller consignment could change the rate, but declining the work would leave him to carry what he can actually staff, rather than the larger departure he can still see when he unfolds the empty page.",
  'The shipment is here, the price is here, and this is the departure. I had nearly reached the part about tomorrow. Let us finish the part that somebody has actually booked first.',
  'Folds the empty half of the order sheet behind today’s load.', 'Is this an ongoing job?',
  'Ravi turns the sheet back. “This load, this shift. I can discuss the next one afterward.” The paid hours, take-home, and priority blocks belong to the single commitment shown below.'),
 'missing_shot:cut':scene('nila_desai',
  "On Nila’s screen, Ravi’s load waits behind the other loads for long enough that you begin noticing how people stand when they do not expect to be watched. She cuts to the moment it moves, improving the pace immediately while removing the stretch that establishes whose turn it was. Ravi calls the second version energetic; Nila rewinds to his motionless freight and lets it remain there through the rest of his compliment. Keeping the queue, choosing the quicker cut, or leaving her to edit privately would each make a different kind of film, though only one preserves the sequence as evidence.",
  'A cut makes the waiting disappear. It doesn’t make the load arrive earlier, although Dad finds that distinction less interesting than the improved pace. Which version do you think people will believe?',
  'Leaves the playhead just before the missing stretch.', 'What would the short cut prove?',
  '“That the load moved,” Nila says. “It would not show whose turn it was.” She restores the two frames side by side without choosing a public version.'),
 'missing_shot:permission':scene('nila_desai',
  "Nila has marked the queue sequence and written the names of the people filmed beneath it, but Ravi gets no farther than the first note before beginning a speech about vindication. She turns the page before his second point, revealing the list he has not yet read. With the contributors’ agreement, that excerpt could answer the particular accusation of jumping the queue; the separate short she might offer Ada could be about waiting without becoming an advertisement for her father. If she keeps the film private, the ordinary dispatch book will remain at the landing, ready to answer an ordinary question about departure order.",
  'I can ask the people in this sequence before showing it. What I cannot do is edit a film proving that my father has never been wrong about freight, or anything else.',
  'Keeps the contributor list beside the marked sequence.', 'Could the dispatch book answer instead?',
  '“Yes,” Nila says. “It has the order of the loads. It is not waiting for a better ending.” Her film does not have to become the record of every argument at the landing.'),
 'broth:batch':scene('pelagia_lio',
  "Lio opens the biscuit packet and counts again, as though the number might improve once the broth is ready, while Safia argues from the queue that appetites are more important than administrative requirements. He sets out a bowl for each order he has actually received, then returns the unused one to the stack without addressing the argument. Buying a serving would put another bowl on the counter; paying for a second batch would require another serving shift as well as another packet. Tea remains available to anyone who would prefer a smaller role in the debate, which Safia is already extending to customers who have not arrived.",
  'An appetite is encouraging. An order tells me how many bowls to put out. I can manage the one, or make a second batch if it is paid for. Tea is allowed to remain tea.',
  'Returns one unused bowl to the stack.', 'Why does another batch need a shift?',
  '“Because opening a packet takes a moment, and serving another pot takes a person,” Lio says. He points to the collection time before Safia can rename it popular demand.'),
 'broth:closing':scene('pelagia_lio',
  "Safia has reached the question of whether a portion can be generous in principle and disappointing in a bowl, a distinction Lio would like to consider after he has eaten something. The last servings are nearly ready, and every time the argument returns to the pot, his attention travels instead to the empty chair beside the counter. An early collection would let him sit while the broth is hot; the named, paid late slot would keep that particular serving available without moving everyone else’s meal. His own spoon is on the table, close enough to reach but still remarkably difficult to use.",
  'I would like to discover whether I agree with her after I’ve had some lunch. Can you collect at the ordinary time? There is one later serving if you want to pay for that arrangement.',
  'Puts a spoon beside his own empty bowl.', 'Does a late serving extend every order?',
  '“Just the named slot,” Lio says. “The other bowls still have their collection times.” He holds the order book open at the single empty line.'),
 'dalloway:sign':scene('mesa_june',
  "When June rings the Dalloway to test the return spring she has repaired, three customers look up from Esperanza’s JUNE’S LAST ORDERS tag and begin ordering with unusual urgency. Kit’s drawing of an empty counter, hung beside the announcement, seems to give the misunderstanding more authority than June can remove by saying she is leaving station announcing, not cooking. Somebody proposes a last supper, and she reaches for the booking book before correcting the phrase. Her station handover, the diner’s ordinary service, and a separately paid farewell meal have somehow become one occasion, while the bell continues to work exactly as intended.",
  'The station. I am leaving the station. The diner will still have a cook, and the cook would like people to read past the word “last” before ordering enough eggs to commemorate her.',
  'Holds a finger under STATION on the corrected note.', 'What is June actually leaving?',
  '“The announcing shifts,” June says. “The diner is staying open, and I am still its cook.” A supper booking buys a meal; it is not a donation to prevent a closure.'),
 'dalloway:service':scene('mesa_june',
  "The incoming announcer calls each plate clearly, allowing June to add a remark about Rosa’s eggs, collect the laugh, and return to cooking without checking where the food has gone. In the tribute recording, the laugh is much more memorable than the plate numbers, which makes it temptingly easy to remove the unremarkable voice that has been getting everybody fed. June listens to both versions with increasing interest. What the station sees will either be a handover that works because another person is doing it, or an evening apparently held together by June alone, depending on which quiet competence survives the cut.",
  'They called the plates. I supplied the remarks. One of those jobs tells people where their supper is, although I admit the other makes a better recording.',
  'Stops the recording before the newcomer’s next call is cut off.', 'Why keep the ordinary calls?',
  'June looks toward the pass. “Because somebody has to get the plate to the right person.” The newcomer’s competence is audible in the full sequence, even where the room is not laughing.'),
 'dalloway:offer':scene('mesa_june',
  "The station rota has four evening spaces: the original handover gives all four to the incoming worker, while the alternative would retain June for two evenings at a rate she reads more than once. She places the diner bookings beside both versions, making a small adjustment so that none of the meals already sold is hidden beneath the better-paid shifts. Supporting the original handover, supporting the offered split, or leaving her to compare them herself would each acknowledge a different part of what she wants. The numbers remain on the table after the flattering part of being wanted in two places has been said.",
  'They have discovered a more persuasive rate at exactly the moment I was finishing leaving. Very flattering. The diner has also discovered that people who paid for supper expect someone to cook it.',
  'Places the two rotas edge to edge with the meal book.', 'Who cooks the booked meals?',
  '“That is the question on this page,” June says, tapping the diner book. If she takes station evenings, those meals still need a willing paid cook or another arrangement for the original diners.'),
 'dalloway:breakfast':scene('mesa_june',
  "The breakfast plates are ready, but the supper commitments have not vanished into the tribute: June lays out the paid tickets, the simpler menu, and the remaining work while the Dalloway waits at the pass. Taking the quoted supper shift would cover the service; accepting the simpler meal would change what arrives; an original payer whose ticket remains unserved can ask for that money back. Then the bell rings for June’s eggs. Her hand reaches toward the kitchen before she remembers which side of breakfast she occupies, and for a moment the person most difficult to release from the handover is the one who wanted it.",
  'A recording does not cook a supper, unfortunately. Here are the meals and the work still to do. Those eggs are mine. I am allowed to inspect my own breakfast without it becoming supervision.',
  'Draws her breakfast plate closer while leaving the tickets on the counter.', 'What happens to an unserved ticket?',
  'June opens the book. “The payer can ask for that ticket’s money back.” Already completed workers keep their pay; a refund does not take anyone else’s wages or meal.'),
 'empty_counter:caption':scene('kit',
  "A customer wants a print of Kit’s empty-counter drawing because it captures the sadness of the diner closing, an interpretation the working cook interrupts by asking whether anybody ordered eggs. Kit points toward the kitchen, where the absence depicted on the page lasted approximately as long as washing a cup, but the customer continues explaining why the mistaken version feels more moving. A clearer caption could return the picture to the ordinary moment it records. A separately commissioned page would give Kit something new to draw; leaving this one in their hands would at least let them decide how much explanation belongs underneath it.",
  'I drew someone being out of the picture. I didn’t draw everyone losing their jobs. Apparently washing a cup has become an insufficiently powerful explanation for an empty counter.',
  'Turns the print toward the sounds coming from the working kitchen.', 'Was the drawing an announcement?',
  '“No. It was a drawing,” Kit says. “A person can step away from a counter and come back.” Kit decides what goes under their work; buying a new page is a separate commission.'),
 'empty_counter:next_page':scene('kit',
  "The next page contains the cup coming back, an event the buyer studies for some time before asking where the loss has gone. Kit looks from the buyer to the sink, makes a small correction to the handle, and leaves the returned object where it was. There is enough happening in that return for them to keep drawing, even if a new event poster, commissioned with its actual details, would be easier for someone else to explain. The ordinary sequence can stand, another work can be ordered, or the shift can end without requiring the next page to justify why nobody has disappeared.",
  'The cup came back. That is something happening. I like the bit where an ordinary object returns and the room has changed just enough for you to notice it.',
  'Keeps the returned cup in the center of the new panel.'),
 'route_green:crate':scene('esperanza_vega',
  "Esperanza has a spare crate space and a route with very little unused time, which become rather different quantities when Inez’s garden exchange and the diner both express an interest. She traces the proposed turn with one finger, then draws a second line for the part she nearly left out when she described it as on the way. The space can carry the diner’s food or the garden’s contribution, but a crate assigned to either destination will cease to be spare. Leaving it unbooked would let her finish the ordinary grocery run without converting every place she passes into another place she owes a stop.",
  'I can fit another stop into a sentence much more easily than into the route. Tell me which delivery you mean, and I will show you the turn that makes it a different journey.',
  'Keeps a finger on the extra turn instead of the straight line.'),
 'route_green:stop':scene('esperanza_vega',
  "At the next stop, the conversation lasts longer than the unloading, until somebody remarks that it would be lovely if Esperanza called in like this every week. She reaches for the route sheet before the invitation acquires a permanent place in her van. Collecting at the early shared stop would let several orders come off together; the separately paid late stop would put one named exception on the page. Declining the extra stop would allow the pleasant conversation to end as a conversation, without quietly assigning its warmth to every future afternoon she drives through the neighborhood.",
  'A pleasant stop can still be a stop. I would like to finish this one before we give every future week the same name. What do you actually need delivered?',
  'Folds the completed part of the route away from the unbooked space.'),
 'commentary:volume':scene('rosa_moreno',
  "Rosa has placed the radio where she can hear the commentary over the conversation, which has accordingly become louder, though neither side appears to consider itself responsible for the competition. June attempts to take an order while Mateo waits for the end of a sentence that extends whenever the score changes. The speech could wait until half-time, the match could keep its own listening table, or your visit could finish before either wins possession of the room. Rosa turns one ear toward you, keeping the other with the commentator whose judgment she has spent most of the afternoon disputing.",
  'I am listening. The commentator is also listening, apparently, although he has considerably more to say about it. Tell me which bit you want quieter before the next result arrives.',
  'Keeps her hand near the dial while waiting for a specific request.'),
 'commentary:result':scene('rosa_moreno',
  "When the result arrives, Rosa repeats it accurately and then begins explaining why the players should have produced it by a different method. Mateo ventures that the score makes an unusually concise ending; she looks at him until he discovers something requiring attention in his cup. Putting the result on the notice would leave her prediction out, while a later replay table would provide a fresh occasion to establish everything the referee should have noticed. Finishing the visit would clear the present table without settling her account of the match, which has reached a level of detail the score cannot reasonably be expected to contain.",
  'Of course I know what happened. I am explaining what they should have done before it happened, which seems rather more useful. You can disagree, but do start at the beginning.',
  'Turns the radio down now that she has the result herself.'),
 'bracken:room':scene('nell_harper',
  "Nell has written EQUIPMENT on the case; Jonah puts his room receipt beside the label, leaving the two descriptions to occupy the same surface. “Just so we’re all admiring the same arrangement.” Ruth’s suitcase waits by the door because his rent has paid for the holiday she is finally taking, an outcome Nell considers proof of how well her introduction worked. “You needed a room, Gran needed a holiday,” she says, testing the drum handle although nobody has asked her to move it. The room already belongs to Jonah’s paid stay and the instrument belongs to Nell, but the place where she intends to sleep remains the one part of her account without a label.",
  'The drum only needs somewhere for a few days. I know exactly how much space it takes up. I can give you the measurements, if that would make this less of a discussion.',
  'Lets go of the handle without moving the drum.', 'Why is there a duvet in the drum?',
  '“It is useful for the sound,” Nell says. Jonah waits. “And for sleeping. Separately.” Ruth’s room has already been rented to Jonah; storing Nell’s instrument would not give Nell a bed there.'),
 'bracken:destination':scene('nell_harper',
  "Mina’s offer of rehearsal storage and Neri’s onward-travel details arrive as two messages concerning the same drum, while Jonah’s request for his floor space requires no message at all. Nell opens both without replying, then studies the case as though it might select the destination that would leave her the fewest unanswered questions. Rehearsal storage would place the instrument near Mina without accepting the musical invitation; taking it onward costs money and removes it from the rehearsal; a separately arranged bed would solve a different part of the evening. Neri remains at their own location, having supplied travel information rather than promised to appear in Alder.",
  'The rehearsal room can take the drum. The onward route can also take the drum, at a rather more expensive rate. Everyone has been wonderfully clear about the instrument. I am beginning to feel under-specified.',
  'Sets the two messages beside the case instead of answering either.', 'Is Neri waiting here?',
  '“No,” Nell says, showing the message. “Those are travel details. They are calling from where they are.” A journey, a rehearsal place, and somewhere to sleep are three separate arrangements.'),
 'bracken:quay':scene('nell_harper',
  "Ruth’s departure happens to use the route Neri described, a coincidence that makes Nell’s separate explanations less easy to keep separate when Neri joins a brief call from their current location. Ruth prepares a farewell film while Jonah tries the phrase “ensuite drummer” on anyone close enough to hear it, and Nell finds herself answering several versions of the same question at once. If the plans were clarified earlier, this is only an awkward goodbye. Otherwise, the luggage, the onward route, and the duvet inside the instrument have assembled an account of the evening that she would have preferred to deliver in a different order.",
  'I was only seeing Gran off. That is a complete sentence. The difficulty is that everyone keeps attaching the other complete sentences to the end of it. Ask me which journey you mean.',
  'Waits beside the luggage while the remote call connects.', 'Which journeys have actually been booked?',
  'Ruth’s holiday is booked. Nell’s onward choice depends on the arrangement already made; Neri is joining by call, not appearing at the quay. The next decision can clarify those facts without booking another person’s trip.'),
 'bracken:night':scene('nell_harper',
  "The Bracken has a destination, and Nell’s evening has finally acquired more than one noun, while Jonah retains the room he paid for rather than the supporting role he nearly acquired in her travel arrangements. A quiet lodging plan would let him sleep; asking about a later opening would require him to have some rest before considering another performance. Nell could also finish the evening without further advice. She smooths a corner of the equipment label that no longer needs smoothing, as Jonah waits with the unmistakable patience of someone hoping the word accommodation will be used again.",
  'I can manage the rest of the evening. I would prefer to manage it without becoming the title of Jonah’s next routine. He has found a surprisingly large amount to say about one room.',
  'Straightens the equipment label before looking back at you.'),
 'late_loaf:batch':scene('hugo',
  "Hugo has counted the bread against the collection slips and discovered that the most flattering request arrived after the arithmetic was complete. Tess would like food for the café and Eli has a pantry plan, but the portions already labeled for the night workers, including Jonah’s paid loaf, cannot become spare merely because the new occasion sounds generous. Buying the offered café quantity or an additional batch would create another order with its own work. Keeping the usual batch would let Hugo finish at the usual time; his blank label remains ready on the bench without anybody’s name on it.",
  'Those tied parcels are the night workers’ bread. Leave them there. I can make up the offered café order separately, or take an extra batch; either way I need the quantity before I start mixing. Which order do you mean?',
  'Keeps the paid collection slips apart from the blank labels.'),
 'late_loaf:name':scene('hugo',
  "The loaf has acquired a description more ambitious than the batch, which Hugo reads aloud, rejects as exaggeration, and then tries once more with a better pause. Tess needs to know what the café can honestly put on its board, while the existing purchasers chiefly need to know when to collect their bread. Keeping Late-Shift Loaf beside its real pickup time would answer that question without manufacturing an exclusive product. A later demonstration could show what makes the bread worth eating after Hugo has slept; leaving the name alone would allow a loaf to leave the bakery with its identity and crust intact.",
  'I did not say it was a new variety. Someone heard an instruction and wrote it as a title. It is, unfortunately, a rather good title. Which part are you asking me to explain?',
  'Holds the label just far enough from the loaf to compare them.'),
 'last_crossing:board':scene('alder_tess',
  "Tess has put the ferry departure and café closing time on the same board, where a guest reads one aloud and treats the other as an invitation to have tea until it happens. Bram points out the walking time; Lucien, who can already think of an exception, waits for a pause long enough to make it sound relevant. Separate lines would clarify the two clocks, while another paid pot would leave both of them where they are. The verified later route is available to anyone willing to exchange the fantasy of an endless evening for a longer, workable journey.",
  'The crossing has a departure, the walk has a length, and I have a closing time. They are all written here. It is extraordinary how often three numbers are mistaken for an invitation to negotiate.',
  'Underlines the time between leaving the café and reaching the ferry.', 'Can we stay until the ferry leaves?',
  '“Only if you intend to watch it from here,” Tess says. Bram points out the walking time. A workable plan needs to leave the café early enough for the actual route.'),
 'last_crossing:closing':scene('alder_tess',
  "As chairs return to their tables, somebody says there is no rush and settles more comfortably into the one still occupied, leaving Tess with an empty cup she refuses to put down again. Bram has the verified route, so letting the café close need not leave the group without a connection or a destination. Tomorrow’s discussion could have its own booked table instead of extending this one by successive final remarks. Leaving with the others would also give the evening a recognizable end, although Lucien has found one more thing whose importance appears to increase as everybody reaches for their coat.",
  'If the last thing is a question about tomorrow, it can wait until tomorrow. I have discovered that people who say “no rush” rarely mean they are about to get up.',
  'Keeps the empty cup in her hand rather than setting it down again.'),
 'pantry_song:list':scene('mina',
  "Mina’s song is at the top of the page, but Eli’s proposed supper and a growing list of names have begun to make it resemble an invitation to an event she does not remember designing. Nell asks whether the drum should come; Mina reads the paper again, trying to locate the listening evening inside the meal. A counted gathering would distinguish actual diners from the twelve chairs in the lyric, while a paid supper for six would give the food its own arrangement. Keeping it smaller would leave the song room to contain people who are not being invited to eat.",
  'I wanted people to hear the song. I am not against people eating; I would simply like to know whether they will hear the ending before asking where to put the bowls.',
  'Moves the lyric clear of the growing guest list.'),
 'pantry_song:listen':scene('mina',
  "With the chairs in place, Mina rests a hand on the page while Eli checks whether the furniture corresponds to the expected guests and Nell waits to hear whether anything belongs in a programme. Mina begins, stops before the line she has been avoiding, and looks toward you without explaining the difficulty again. Listening all the way through would give her a chance to discover what the ending sounds like in this room. An invitation to sing one song at the paid event would be another arrangement, while leaving the rehearsal for later would not, by itself, turn an unfinished song into a failed one.",
  'There is a line I keep stopping before. I would like to try getting through it once while everybody listens. Afterward you can tell me what you heard, rather than what else the evening could become.',
  'Keeps her hand on the page until the counting stops.'),
 'laundry:quote':scene('qiao_chen',
  "Qiao writes the ordinary turnaround and rush price on different lines, allowing Mei to see exactly how much it would cost to replace the afternoon she had hoped to borrow for rehearsal. When Akira describes the request as very small, Qiao asks whether he means the quantity or his feelings about the quotation. An ordinary booking would take the ordinary time; paying the rush rate would purchase a different place in her working day. Using the stock already available would leave the afternoon unbooked, a condition that neither the empty space on the form nor Mei’s hopeful expression has yet altered.",
  'How much, and when? Those are excellent questions. “It shouldn’t take long” is more of a hope. I have put the two prices where everybody can admire the difference.',
  'Turns the quote so that both prices face the customer.'),
 'laundry:invitation':scene('qiao_chen',
  "Mei’s invitation to choir produces a mock price list from Qiao, who has assigned separate rates to attending, listening, and possibly enjoying herself. When Mei asks whether she should stop inviting her, the list goes beneath the genuine collection slip with rather less ceremony than it received on arrival. A short visit after pickup would let Qiao hear something without giving up the whole evening; a later weekend trip would accommodate the work she has chosen. Declining this rehearsal would answer today’s invitation, though she becomes abruptly precise when anyone tries to make that answer apply to all the others.",
  'Do keep asking. I have only objected to this particular arrangement, and perhaps the tone of the invitation, and the hour. There is no reason to make a general policy of it.',
  'Slides the mock price list beneath the genuine collection slip.'),
 'small_pause:handover':scene('akira_mori',
  "A cup of the café’s separately purchased Kestrel tea cools beside Akira’s handover while he explains why the supplier’s long-ago journey to the airport illuminates the present sandwich order. His colleague needs today’s quantities, which are on the first page beneath several pages devoted to their context. Testing the short handover could let Akira leave for rehearsal without remaining the person every question returns to; taking the quoted canteen shift would put another name beside the work. Keeping the old rota would keep the canteen running too, though his small theatrical entrance would have to wait through another explanation of why he cannot yet leave.",
  'The quantities are on the first page. The other pages are context. I appreciate that a person making lunch may not require the complete history of how we came to have this supplier.',
  'Squares the extra pages beneath the one with today’s quantities.'),
 'small_pause:pause':scene('akira_mori',
  "Akira’s entrance contains two seconds of silence, but asking the director to rehearse it first would require him to describe the part as something that could be finished near the beginning. He explains the significance of the pause until Hana looks at the clock, an intervention that appears to support the director’s likely view of its duration. A short slot would let him keep the changed handover; attending the whole rehearsal would mean retaining the old rota another cycle. He would like either arrangement to convey the seriousness of the performance without making the silence any longer than it already is.",
  'Two seconds is the duration, not the significance. I can ask to do the entrance first. I would simply prefer the request not to suggest that everyone could have finished with me in a moment.',
  'Closes the script with a finger still marking the entrance.'),
 'timetable:times':scene('glass_ren',
  "The notices for Qiao’s collection and Akira’s rehearsal have been placed close enough together to imply a journey that cannot be made on the advertised early train. Ren unfolds the ordinary timetable, revealing a later service that has existed throughout the discussion without attracting enough enthusiasm to become a headline. Putting it on the notices would let people choose a real wait; keeping the early train would require shorter event slots rather than a more accommodating railway. Your usual journey remains available, while Ren prepares to explain the alternatives with a completeness that may itself require the later departure.",
  'The later service was there all along. It involves a wait, which may be less inconvenient than attempting to be in both places at the same time. Shall I give you the departure first?',
  'Places the later departure beside the two incompatible notices.'),
 'timetable:platform':scene('glass_ren',
  "Ren has reduced the notice to three useful facts when a passenger asks a question that appears to open the door to six adjacent answers. The platform corner could give a group somewhere definite to assemble, but reserving a place to meet would not board the train or purchase anybody’s journey. Keeping the sign to departure, platform, and fallback would preserve the distinction; traveling independently would let the same timetable serve a person who does not need to be counted into the group. Ren lowers the chalk, leaving a margin that has begun to look like a difficult personal achievement.",
  'Departure, platform, fallback. I have left a margin because people ask questions. I am trying to resist filling it with the answers before they have asked them.',
  'Lowers the chalk without using the remaining space.'),
 'portrait:chair':scene('liang_chen',
  "Liang has found the light in which he looks least as though he has been searching for it, although the chair that produces this effect also obstructs the room’s small stage. Jian waits at the supervised drawing session while the sitter makes one final adjustment to an arrangement he continues to describe as casual. A bright side corner would keep the stage clear, booking the main position would move rehearsal, and a shorter sitting would return the chair sooner. Everyone appears ready except Liang’s spontaneous expression, which he is still comparing with another, slightly less spontaneous possibility.",
  'The light does make a difference. I am perfectly willing to appear informal somewhere sensible. Does that corner make me look as though I have chosen it too carefully?',
  'Moves one hand from the chair before deciding where it should rest.'),
 'portrait:expression':scene('liang_chen',
  "Jian’s drawing contains the exact effort Liang has put into relaxing, a resemblance he recognizes immediately before asking whether a tiny correction could make it more natural. Jian explains that a drawing is not evidence the sitter was taken by surprise, while Liang lowers the shoulder whose position has become unexpectedly informative. Leaving the informal pose would preserve that observation; asking both about a small display would give it another audience. Keeping the sitting private would leave the portrait with its agreed owner and return the chair on time, without requiring the drawing to settle how deliberately a person may appear at ease.",
  'I do look like that. I was wondering whether I might look like that slightly less deliberately. It is not a criticism of the drawing. The drawing may be rather too observant.',
  'Studies the depicted shoulder before lowering his own.'),
 'six_chairs:intro':scene('ines_valdes',
  "Inés promises not to disclose the ending, then begins explaining why the final scene makes the opening impossible to appreciate without precisely the information she has undertaken to withhold. Ada waits beside the projector with the agreed two-minute cue, while several listeners grow anxious for entirely different reasons. Giving the cue would let the film begin; paying for an earlier slot would give Inés’s complete introduction its own time rather than borrowing the screening’s. Coming for the film and leaving the intervention to Ada remains possible, provided you arrive before context has acquired another justification for continuing.",
  'I can stop at two minutes. I would merely like everyone to understand why I am leaving certain things out. The absence of context can itself give quite the wrong impression.',
  'Keeps a finger between the pages of an introduction still folded shut.'),
 'six_chairs:tea':scene('ines_valdes',
  "The credits release Inés from the restriction that gave her introduction its shape, just as the projectionist begins gathering the things that will allow their evening to end. Ada can offer a separate tea slot, where the argument could continue without depending on the person closing the equipment; a short-film programme would require another date rather than this screening expanding into the next one. Buying the tea arrangement would move the discussion to a different table. Leaving at the credits would preserve a perfectly ordinary ending, though Inés has just found the sentence she spent the opening trying not to say.",
  'Now we can discuss the ending without disguising it as something else. Ada says there is one pot of tea. I suppose we shall have to decide which of us is willing to drink slowly.',
  'Lets the folded introduction close as the end credits disappear.'),
 'closing_hours:notice':scene('farah_hussain',
  "Farah’s new shop notice devotes three lines to a villain’s romantic betrayal and relegates the changed closing time to a footnote, which may explain why the regular customer keeps arriving too late to collect. She wants to reach the radio-drama group, but has prepared a defense of leaving that is substantially longer than the practical information the customer needs. Moving the hours above the argument would make the ordinary arrangement legible. A paid late collection would create a named exception, while shopping at the posted time would allow her to discover whether closing is possible without persuading everyone to care about the episode.",
  'I am not closing because of the betrayal. I am closing in time to hear what happens after it. That is a practical distinction, though apparently I have hidden the practical part at the bottom.',
  'Reads the tiny closing-time line without lowering the notice.'),
 'closing_hours:episode':scene('farah_hussain',
  "The character Farah has defended does something she cannot defend, leaving her to assemble a sufficiently severe objection while somebody offers her the listening group’s spare keys. She looks from them to next week’s episode, which remains in her diary despite everything she is saying about the writers. Keeping her a guest would separate returning to hear the consequences from becoming responsible for opening the room. Buying the offered biscuits would prepare for a meeting she claims to have lost all faith in, while leaving before the argument finishes would still permit the argument to occupy the people who remain.",
  'I shall certainly listen next week. Somebody ought to know whether they correct this. That does not mean I should be the person opening the room for everybody else to be disappointed in it.',
  'Leaves the spare keys on the table beside her open diary.'),
 'nine_locks:rule':scene('sami',
  "At the adult-run public table, Vera wins under the rule everybody has just described as friendly, then hears Sami ask whether the instruction was clear and wonders whether he is preparing to discount the result. He holds the sheet between them, discovering how difficult it is to begin an editorial discussion at the moment the other player expects a score announcement. Counting the win and continuing would separate those questions; a quick rematch could fit before the booking ends. Stopping after the round would leave Vera’s victory intact and Sami free to examine a rule that someone has successfully used against him.",
  'It counted. I was asking whether the rule explained itself. Those are different questions, although I can see why asking mine immediately after losing has made them look suspiciously related.',
  'Leaves Vera’s score untouched while turning back to the rule sheet.'),
 'nine_locks:demo':scene('sami',
  "The demonstration reaches its booked finish while Vera repeats the score to a new arrival and Sami begins gathering pieces for the group waiting to use the table. Another adult-run event could display the rules, but the poster cannot decide whether Vera wants to play again or reproduce this particular result for a different audience. Finishing on time would leave the next activity its place; asking Sami about a display copy would move the sheet rather than enlist the player. Future games can also remain for another day, with the present one allowed to end as something useful that has already happened.",
  'We have a finished game and a rule someone managed to use against me. That is useful. I can take the sheet elsewhere without pretending it comes with the same player or the same result.',
  'Collects the rule sheet while leaving Vera room to keep her own game box.'),
 'first_shift:batch':scene('saffron_leila',
  "Leila can fit one additional paid batch of Dock Folds before the griddle changes over, a quantity that the cinema and repair crew would both find convenient without becoming large enough to feed both. Rafael looks at the portions already labeled for regular customers, and Leila moves the proposed extra order onto a clean page so that nobody mistakes their lunches for a possible solution. Buying the batch for either new destination would put its name on that page. Leaving it unbooked would let her serve the ordinary customers and turn the griddle over, without first cooking for the more interesting gathering nobody has actually paid to feed.",
  'One extra batch. The people on these labels are also real customers, even if nobody has organized an event around their lunch. Which new table is this one actually going to?',
  'Sets the blank order page beside the labeled regular portions.'),
 'first_shift:break':scene('saffron_leila',
  "Tomas opens the Gullwing tin just as somebody asks when the repair will be finished, but Leila waits until he has removed the lid before answering the question about collection. The repair can wait through his agreed break; a willing adult could take the quoted food handover without inheriting his specialist work. Choosing the later collection would give the lunch its own time, while working the food shift would keep that separate task moving as he eats. Leaving the ordinary schedule in place would also produce a break, which the remarkably well-designed tin has proved unable to arrange without help from the people surrounding it.",
  'Let him take a hot first bite before we discuss the rest of the afternoon. The food handover is one job. His specialist repair is another, and neither improves because he has missed lunch.',
  'Keeps the collection sheet away from the open lunch tin.'),
};

